//
// rom_fetch_test — src/RomFetch, src/RomStore and src/HostProcess with the
// network replaced by a fake server (FetchOptions::download). Asset-free:
// the dumps are synthetic catalogue rows over generated bytes, so no Apple
// byte is needed and nothing leaves the host.
//
//   archive ok                → every dump from the archive
//   archive 403               → RetroBIOS, loose file and zip member;
//                               an archive-only dump fails with the
//                               archive's reason
//   archive answers HTML      → treated as down
//   archive member wrong      → that dump from RetroBIOS
//   RetroBIOS bytes wrong     → refused, nothing written
//   archive is a zip bomb     → refused from its directory, fallback
//   wrong file in place       → kept in roms-replaced/, then replaced
//   right file in place       → left alone
//   cancel                    → stops between dumps, reports it
//   a wrong file found first  → the save is reported as not used
//   curl argv, curl reasons, writableRomsDir, installRom refusals, a
//   symlink at the destination, and the process runner itself.

#include "RomFetch.h"
#include "RomStore.h"
#include "HostProcess.h"
#include "ZipFixture.h"

#include "Crc32.h"
#include "Sha256.h"

#include <chrono>
#include <cstdio>
#include <map>
#include <string>

#if !defined(_WIN32)
#include <unistd.h>
#endif

using namespace pom68k;
using namespace pom68k::roms;
namespace fs = std::filesystem;

static int gFails = 0;
static void check(bool ok, const std::string& what) {
    std::printf("%s %s\n", ok ? "ok  " : "FAIL", what.c_str());
    if (!ok) ++gFails;
}

static std::vector<std::uint8_t> noise(std::size_t n, std::uint32_t seed) {
    std::vector<std::uint8_t> v(n);
    for (auto& b : v) { seed = seed * 1664525u + 1013904223u; b = std::uint8_t(seed >> 24); }
    return v;
}

// Three synthetic dumps: A loose on RetroBIOS, B inside a RetroBIOS zip,
// C only in the POM68K archive.
struct Fixture {
    std::vector<std::uint8_t> a = noise(4096, 1), b = noise(2048, 2), c = noise(1024, 3);
    std::string shaA = sha256Hex(a), shaB = sha256Hex(b), shaC = sha256Hex(c);
    RomDump dumps[3];
    Fixture() {
        dumps[0] = {.id = "test-a", .label = "Test A", .kind = RomKind::Firmware,
                    .need = RomNeed::Substitute, .path = "roms/test/a.bin", .alsoAt = "",
                    .size = 4096, .sha256 = shaA.c_str(), .crc32 = crc32(a), .checksum = nullptr,
                    .profiles = "lcii", .absent = "", .rootRelative = false,
                    .retroBios = "bios/Test Dir/a.bin", .retroBiosMember = nullptr};
        dumps[1] = {.id = "test-b", .label = "Test B", .kind = RomKind::Firmware,
                    .need = RomNeed::Substitute, .path = "roms/test/b.bin", .alsoAt = "",
                    .size = 2048, .sha256 = shaB.c_str(), .crc32 = crc32(b), .checksum = nullptr,
                    .profiles = "lcii", .absent = "", .rootRelative = false,
                    .retroBios = "bios/Test/set.zip", .retroBiosMember = "b.bin"};
        dumps[2] = {.id = "test-c", .label = "Test C", .kind = RomKind::Firmware,
                    .need = RomNeed::Optional, .path = "roms/test/c.bin", .alsoAt = "",
                    .size = 1024, .sha256 = shaC.c_str(), .crc32 = crc32(c), .checksum = nullptr,
                    .profiles = "lcii", .absent = "", .rootRelative = false,
                    .retroBios = nullptr, .retroBiosMember = nullptr};
    }
    std::vector<const RomDump*> wanted() const { return {&dumps[0], &dumps[1], &dumps[2]}; }
    std::vector<std::uint8_t> archive() const {
        return testzip::make({testzip::stored("roms/test/a.bin", a),
                              testzip::stored("roms/test/b.bin", b),
                              testzip::stored("roms/test/c.bin", c)});
    }
    std::vector<std::uint8_t> rbZip() const {
        return testzip::make({testzip::stored("other.bin", noise(10, 9)),
                              testzip::stored("b.bin", b)});
    }
};

// url → body; an absent url answers like curl -f on a 404.
struct FakeServer {
    std::map<std::string, std::vector<std::uint8_t>> bodies;
    std::map<std::string, std::string> refusals;
    std::vector<std::string> asked;
    DownloadFn fn() {
        return [this](const std::string& url, const fs::path& dest, std::string& err) {
            asked.push_back(url);
            if (auto r = refusals.find(url); r != refusals.end()) { err = r->second; return false; }
            auto it = bodies.find(url);
            if (it == bodies.end()) { err = "HTTP 404"; return false; }
            testzip::writeFile(dest, it->second);
            return true;
        };
    }
};

static FakeServer serverFor(const Fixture& fx, bool archive) {
    FakeServer s;
    if (archive) s.bodies[kRomArchiveUrl] = fx.archive();
    else s.refusals[kRomArchiveUrl] = "the server refused the download (HTTP 403)";
    s.bodies[retroBiosUrl(fx.dumps[0])] = fx.a;
    s.bodies[retroBiosUrl(fx.dumps[1])] = fx.rbZip();
    return s;
}

static bool holds(const fs::path& p, const std::vector<std::uint8_t>& want) {
    std::error_code ec;
    return fs::is_regular_file(p, ec) && testzip::readFile(p) == want;
}

static bool noStrayFiles(const fs::path& romsDir) {
    std::error_code ec;
    for (auto it = fs::recursive_directory_iterator(romsDir, ec);
         !ec && it != fs::recursive_directory_iterator(); it.increment(ec)) {
        const std::string n = it->path().filename().string();
        if (n.find(".part-") != std::string::npos || n.rfind(".fetch-", 0) == 0) return false;
    }
    return true;
}

static void fetchScenarios() {
    const Fixture fx;
    {
        testzip::TempDir t("fetch-ok");
        FakeServer s = serverFor(fx, true);
        FetchOptions o;
        o.download = s.fn();
        int ticks = 0;
        o.progress = [&](const FetchProgress& p) { ++ticks; (void)p; };
        const RomSearch search{t.path, {}, {}};
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), search, o);
        check(r.saved == 3 && r.fromArchive == 3 && r.failed == 0,
              "archive ok: 3 saved from the archive (" + r.summary + ")");
        check(holds(t.path / "roms/test/a.bin", fx.a) && holds(t.path / "roms/test/c.bin", fx.c),
              "archive ok: files installed at their catalogue paths");
        check(s.asked.size() == 1, "archive ok: one download, RetroBIOS never asked");
        check(ticks >= 4, "archive ok: progress reported");
        check(noStrayFiles(t.path / "roms"), "archive ok: no scratch or partial file left");
        check(checkRom(fx.dumps[1], search).state == RomState::Verified,
              "archive ok: the store now verifies the dump");
    }
    for (const bool html : {false, true}) {
        testzip::TempDir t(html ? "fetch-html" : "fetch-403");
        FakeServer s = serverFor(fx, false);
        if (html) {
            s.refusals.clear();
            const std::string page = "<!DOCTYPE html><html><body>Item not found</body></html>";
            s.bodies[kRomArchiveUrl] = std::vector<std::uint8_t>(page.begin(), page.end());
        }
        FetchOptions o;
        o.download = s.fn();
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), {t.path, {}, {}}, o);
        const std::string tag = html ? "archive HTML: " : "archive 403: ";
        check(r.saved == 2 && r.fromRetroBios == 2 && r.failed == 1,
              tag + "A and B from RetroBIOS, C failed (" + r.summary + ")");
        check(holds(t.path / "roms/test/a.bin", fx.a) && holds(t.path / "roms/test/b.bin", fx.b),
              tag + "loose file and zip member installed");
        check(!fs::exists(t.path / "roms/test/c.bin"), tag + "archive-only dump not written");
        check(!r.archiveError.empty() &&
                  r.summary.find("archive.org is unavailable") != std::string::npos,
              tag + "the summary names the archive outage");
        check(r.items.size() == 3 && !r.items[2].ok &&
                  r.items[2].error.find(html ? "not a zip" : "403") != std::string::npos,
              tag + "C carries the archive's reason (" +
                  (r.items.size() == 3 ? r.items[2].error : std::string("?")) + ")");
    }
    {
        testzip::TempDir t("fetch-badmember");
        FakeServer s = serverFor(fx, true);
        auto wrongA = fx.a;
        wrongA[100] ^= 0xFF;
        s.bodies[kRomArchiveUrl] = testzip::make({testzip::stored("roms/test/a.bin", wrongA),
                                                  testzip::stored("roms/test/c.bin", fx.c)});
        auto wrongB = fx.b;
        wrongB[0] ^= 1;
        s.bodies[retroBiosUrl(fx.dumps[1])] = testzip::make({testzip::stored("b.bin", wrongB)});
        FetchOptions o;
        o.download = s.fn();
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), {t.path, {}, {}}, o);
        check(r.items.size() == 3 && r.items[0].ok && r.items[0].source == "RetroBIOS",
              "archive member not the dump: fetched from RetroBIOS instead");
        check(r.items.size() == 3 && !r.items[1].ok &&
                  r.items[1].error.find("SHA-256") != std::string::npos,
              "RetroBIOS bytes not the dump: refused by SHA-256");
        check(!fs::exists(t.path / "roms/test/b.bin"), "refused bytes were never written");
        check(r.items.size() == 3 && r.items[2].ok && r.items[2].source == "archive",
              "the archive's good member still used");
    }
    {
        testzip::TempDir t("fetch-bomb");
        FakeServer s = serverFor(fx, true);
        std::vector<testzip::Member> ms;
        for (int i = 0; i < 4; ++i) {
            testzip::Member m = testzip::stored("x" + std::to_string(i), {1, 2, 3});
            m.size = 0x7FFFFFFF;   // 2 GiB each, declared
            ms.push_back(m);
        }
        s.bodies[kRomArchiveUrl] = testzip::make(ms);
        FetchOptions o;
        o.download = s.fn();
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), {t.path, {}, {}}, o);
        check(r.archiveError.find("refusing") != std::string::npos && r.fromRetroBios == 2,
              "zip bomb refused from its directory, RetroBIOS used (" + r.archiveError + ")");
    }
    {
        testzip::TempDir t("fetch-backup");
        FakeServer s = serverFor(fx, true);
        const auto old = noise(4096, 77);
        testzip::writeFile(t.path / "roms/test/a.bin", old);
        testzip::writeFile(t.path / "roms/test/b.bin", fx.b);
        FetchOptions o;
        o.download = s.fn();
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), {t.path, {}, {}}, o);
        check(r.saved == 3 && r.replaced == 1, "backup: one replaced (" + r.summary + ")");
        check(holds(t.path / "roms/test/a.bin", fx.a), "backup: the dump replaced the wrong file");
        const std::string backup = r.items.empty() ? "" : r.items[0].backup;
        check(!backup.empty() && holds(backup, old) &&
                  fs::path(backup).parent_path() == t.path / "roms-replaced" / "test",
              "backup: the old file kept, byte for byte, in roms-replaced/ (" + backup + ")");
        check(r.items.size() == 3 && r.items[1].backup.empty(),
              "backup: a right file in place is left alone, nothing kept");
        check(r.summary.find("roms-replaced") != std::string::npos,
              "backup: the summary says where the old file went");
    }
    {
        testzip::TempDir t("fetch-cancel");
        FakeServer s = serverFor(fx, false);
        bool stop = false;
        FetchOptions o;
        o.download = [&](const std::string& url, const fs::path& dest, std::string& err) {
            const bool ok = s.fn()(url, dest, err);
            if (url == retroBiosUrl(fx.dumps[0])) stop = true;   // the user hits Cancel
            return ok;
        };
        o.cancelled = [&] { return stop; };
        const FetchResult r = fetchRomsInto(t.path / "roms", fx.wanted(), {t.path, {}, {}}, o);
        check(r.cancelled && r.items.size() <= 1 && r.summary.rfind("Cancelled", 0) == 0,
              "cancel: the run stops after the current download (" + r.summary + ")");
        check(!fs::exists(t.path / "roms/test/b.bin"), "cancel: nothing fetched afterwards");
        check(noStrayFiles(t.path / "roms"), "cancel: scratch removed");
    }
    {
        // romsDir is <work>/../roms, but <work>/roms holds a wrong copy
        // that the runtime finds first.
        testzip::TempDir t("fetch-shadow");
        FakeServer s = serverFor(fx, true);
        testzip::writeFile(t.path / "work/roms/test/c.bin", noise(1024, 5));
        FetchOptions o;
        o.download = s.fn();
        const FetchResult r =
            fetchRomsInto(t.path / "roms", {&fx.dumps[2]}, {t.path / "work", {}, {}}, o);
        check(r.failed == 1 && r.items.size() == 1 &&
                  r.items[0].error.find("found first") != std::string::npos,
              "shadow: a save the runtime will not load is reported (" +
                  (r.items.empty() ? std::string() : r.items[0].error) + ")");
    }
    {
        // The real catalogue on an empty tree, both sources dark: every
        // entry is wanted, the one asked for fails cleanly.
        testzip::TempDir t("fetch-real");
        FakeServer s;
        s.refusals[kRomArchiveUrl] = "HTTP 403";
        const RomSearch search{t.path, {}, {}};
        check(romsToFetch(search).size() == kRomDumpCount,
              "empty tree: every catalogue entry is to fetch");
        FetchOptions o;
        o.download = s.fn();
        o.only = {"cuda-341s0788"};
        const FetchResult r = fetchRoms(search, o);
        check(r.failed == 1 && r.saved == 0 && r.items.size() == 1 &&
                  r.items[0].error.find("RetroBIOS: HTTP 404") != std::string::npos,
              "both sources dark: a clean failure naming both (" +
                  (r.items.empty() ? r.summary : r.items[0].error) + ")");
        check(s.asked.size() == 2 && s.asked[1] == retroBiosUrl(*findRomDump("cuda-341s0788")),
              "the RetroBIOS URL asked is the pinned one");
    }
}

static void storeScenarios() {
    const Fixture fx;
    {
        testzip::TempDir t("install");
        const fs::path roms = t.path / "roms";
        auto shortA = fx.a;
        shortA.pop_back();
        InstallOutcome o = installRom(roms, fx.dumps[0], shortA);
        check(!o.ok && o.error.find("bytes, expected") != std::string::npos &&
                  !fs::exists(roms / "test/a.bin"),
              "installRom: wrong size refused, nothing written");
        auto wrong = fx.a;
        wrong[5] ^= 0x40;
        o = installRom(roms, fx.dumps[0], wrong);
        check(!o.ok && o.error.find("SHA-256") != std::string::npos && !fs::exists(roms / "test/a.bin"),
              "installRom: wrong SHA-256 refused, nothing written");
        o = installRom(roms, fx.dumps[0], fx.a);
        check(o.ok && !o.unchanged && holds(roms / "test/a.bin", fx.a), "installRom: installs");
        o = installRom(roms, fx.dumps[0], fx.a);
        check(o.ok && o.unchanged && o.backup.empty(), "installRom: same bytes again → unchanged");
        check(replacedRomsDir(roms) == t.path / "roms-replaced",
              "roms-replaced/ is a sibling of roms/, outside the signature scan");
#if !defined(_WIN32)
        // A symlink at the destination pointing at a wrong file elsewhere:
        // the link is replaced, its target never written.
        const fs::path target = t.path / "private" / "b-original.bin";
        const auto original = noise(2048, 42);
        testzip::writeFile(target, original);
        fs::create_directories(roms / "test");
        fs::create_symlink(target, roms / "test/b.bin");
        o = installRom(roms, fx.dumps[1], fx.b);
        check(o.ok && !o.backup.empty() && holds(target, original) &&
                  !fs::is_symlink(roms / "test/b.bin") && holds(roms / "test/b.bin", fx.b),
              "installRom: a symlink is replaced, its target untouched, its bytes kept");
#endif
    }
    {
        testzip::TempDir t("dest");
        fs::create_directories(t.path / "a/roms");
        check(writableRomsDir({t.path / "a", {}, {}}).romsDir == t.path / "a/roms",
              "writableRomsDir: <wd>/roms when it exists");
        fs::create_directories(t.path / "b/roms");
        fs::create_directories(t.path / "b/build");
        check(writableRomsDir({t.path / "b/build", {}, {}}).romsDir == t.path / "b/roms",
              "writableRomsDir: <wd>/../roms for a run from build/");
        fs::create_directories(t.path / "c");
        const RomDestination fresh = writableRomsDir({t.path / "c", {}, {}});
        check(fresh.ok() && fresh.romsDir == t.path / "c/roms" && !fs::exists(t.path / "c/roms"),
              "writableRomsDir: a new <wd>/roms, not created by asking");
        fs::create_directories(t.path / "POM68K.app/Contents/Resources");
        const RomDestination app = writableRomsDir({t.path / "POM68K.app/Contents/Resources", {}, {}});
        check(!app.ok() && app.error.find("bundle") != std::string::npos,
              "writableRomsDir: never inside a .app bundle");
#if !defined(_WIN32)
        if (::geteuid() != 0) {
            fs::create_directories(t.path / "d/roms");
            fs::permissions(t.path / "d/roms", fs::perms::owner_read | fs::perms::owner_exec);
            check(!writableRomsDir({t.path / "d", {}, {}}).ok(),
                  "writableRomsDir: a read-only roms/ is refused");
            fs::permissions(t.path / "d/roms", fs::perms::owner_all);
        }
#endif
    }
}

static void curlScenarios() {
    const std::vector<std::string> want = {
        "-fsSLg", "--proto", "=https", "--proto-redir", "=https",
        "--max-filesize", std::to_string(kMaxDownloadBytes), "--connect-timeout", "15",
        "--retry", "2", "--max-time", "300", "-o", "/tmp/out", "https://example.invalid/x"};
    check(curlArguments("https://example.invalid/x", "/tmp/out") == want,
          "curl argv pinned: HTTPS-only (first request and redirects), size cap, timeouts, no glob");
    check(curlFailureReason(22).find("403") != std::string::npos &&
              curlFailureReason(56).find("403") != std::string::npos,
          "curl exit 22/56 explained as an HTTP refusal");
    check(curlFailureReason(6).find("resolve") != std::string::npos, "curl exit 6 explained");
    check(std::string(kRomArchiveUrl) == "https://archive.org/download/pom68k_firm/pom68k_firm.zip",
          "archive URL pinned");
    check(romFetchAvailable(), "native build: fetch available");
}

static void processScenarios() {
    using host::windowsCommandLine;
    check(windowsCommandLine("curl", {"-o", "C:\\a b\\x.zip", "say \"hi\"", "tail\\"}) ==
              "curl -o \"C:\\a b\\x.zip\" \"say \\\"hi\\\"\" tail\\",
          "Windows quoting: spaces, embedded quotes, trailing backslash");
    check(windowsCommandLine("p", {""}) == "p \"\"", "Windows quoting: empty argument");
#if !defined(_WIN32)
    auto r = host::runHostProcess("sh", {"-c", "exit 3"}, 10000);
    check(r.started && r.exitCode == 3 && !r.succeeded(), "process: exit status returned");
    r = host::runHostProcess("sh", {"-c", "exit 0"}, 10000);
    check(r.succeeded(), "process: success");
    r = host::runHostProcess("pom68k-no-such-program-xyz", {}, 10000);
    check(!r.started && r.error.find("not found") != std::string::npos,
          "process: a missing program is reported (" + r.error + ")");
    auto t0 = std::chrono::steady_clock::now();
    r = host::runHostProcess("sleep", {"20"}, 300);
    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                  std::chrono::steady_clock::now() - t0).count();
    check(r.timedOut && ms < 5000, "process: killed at the deadline (" + std::to_string(ms) + " ms)");
    t0 = std::chrono::steady_clock::now();
    int polls = 0;
    r = host::runHostProcess("sleep", {"20"}, 60000, [&] { return ++polls > 3; });
    ms = std::chrono::duration_cast<std::chrono::milliseconds>(
             std::chrono::steady_clock::now() - t0).count();
    check(r.stopped && ms < 5000, "process: stopped on request (" + std::to_string(ms) + " ms)");
#endif
}

int main() {
    curlScenarios();
    storeScenarios();
    fetchScenarios();
    processScenarios();
    std::printf("%s rom_fetch_test (%d failure%s)\n", gFails ? "FAIL" : "PASS", gFails,
                gFails == 1 ? "" : "s");
    return gFails ? 1 : 0;
}
